package com.example.notification_service.configuration;
import io.micrometer.core.instrument.MeterRegistry;import org.aopalliance.aop.Advice;import org.springframework.amqp.AmqpRejectAndDontRequeueException;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.config.*;import org.springframework.amqp.rabbit.connection.ConnectionFactory;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;
@Configuration public class RabbitTopologyConfiguration{@Bean Declarables notificationTopology(@Value("${notification.messaging.exchange}")String exchange,@Value("${notification.messaging.queue}")String queue,@Value("${notification.messaging.submitted-key}")String submitted,@Value("${notification.messaging.status-key}")String status,@Value("${notification.messaging.dlx}")String dlx,@Value("${notification.messaging.dlq}")String dlq){TopicExchange events=ExchangeBuilder.topicExchange(exchange).durable(true).build();FanoutExchange dead=ExchangeBuilder.fanoutExchange(dlx).durable(true).build();Queue notifications=QueueBuilder.durable(queue).deadLetterExchange(dlx).build();Queue deadQueue=QueueBuilder.durable(dlq).build();return new Declarables(events,dead,notifications,deadQueue,BindingBuilder.bind(notifications).to(events).with(submitted),BindingBuilder.bind(notifications).to(events).with(status),BindingBuilder.bind(deadQueue).to(dead));}
 @Bean Advice notificationRetryAdvice(@Value("${notification.messaging.retry-attempts}")int attempts,MeterRegistry meter){return RetryInterceptorBuilder.stateless().maxRetries(Math.max(0,attempts-1)).backOffOptions(200,2.0,2000).recoverer((message,cause)->{meter.counter("notification.events.dlq").increment();throw new AmqpRejectAndDontRequeueException("Notification retries exhausted",cause);}).build();}
 @Bean SimpleRabbitListenerContainerFactory rabbitListenerContainerFactory(ConnectionFactory connectionFactory,Advice notificationRetryAdvice,@Value("${spring.rabbitmq.listener.simple.prefetch:10}")int prefetch){var f=new SimpleRabbitListenerContainerFactory();f.setConnectionFactory(connectionFactory);f.setPrefetchCount(prefetch);f.setDefaultRequeueRejected(false);f.setAdviceChain(notificationRetryAdvice);return f;}}
